import java.util.*;

public class TextEditing {
    public static int[] analyze(String s) {
        int max = 0;
        int currentRun = 0;
        int totalWords = 0;
        int insideWords = 0;
        boolean maxInside = false;
        boolean wordsInside = false;
        boolean inWord = false;

        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == '(') {
                maxInside = true;
                wordsInside = true;
            } else if (ch == ')') {
                maxInside = false;
                currentRun = 0;
                totalWords += insideWords;
                insideWords = 0;
                inWord = false;
                wordsInside = false;
            } else {
                if (!maxInside) {
                    if (ch == '_') {
                        currentRun = 0;
                    } else {
                        currentRun++;
                        if (currentRun > max) {
                            max = currentRun;
                        }
                    }
                }
                if (wordsInside) {
                    if (ch == '_') {
                        inWord = false;
                    } else {
                        if (!inWord) {
                            insideWords++;
                        }
                        inWord = true;
                    }
                }
            }
        }
        return new int[] { max, totalWords };
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();
        int[] result = analyze(s);
        System.out.println(result[0] + " " + result[1]);
    }
}
